     1→/**
     2→ * GEDCOM 5.5.1 Parser
     3→ * Handles parsing of GEDCOM format files into structured TypeScript objects
     4→ */
     5→
     6→import type {
     7→  GedcomFile,
     8→  GedcomLine,
     9→  GedcomRecord,
    10→  ParsedDate,
    11→  ParsedIndividual,
    12→  ParsedFamily,
    13→  ValidationError,
    14→} from "./types";
    15→
    16→export class GedcomParser {
    17→  private lines: GedcomLine[] = [];
    18→  private records: GedcomRecord[] = [];
    19→  private errors: ValidationError[] = [];
    20→
    21→  /**
    22→   * Parse GEDCOM 5.5.1 text into structured format
    23→   */
    24→  parse(content: string): GedcomFile {
    25→    this.lines = [];
    26→    this.records = [];
    27→    this.errors = [];
    28→
    29→    // Split into lines and filter empty lines
    30→    const rawLines = content.split(/\r?\n/).filter((line) => line.trim());
    31→
    32→    // Parse each line and handle continuations
    33→    this.parseLines(rawLines);
    34→
    35→    // Build hierarchical record structure
    36→    this.buildRecords();
    37→
    38→    // Extract specific records
    39→    const header = this.records.find((r) => r.type === "HEAD");
    40→    const trailer = this.records.find((r) => r.type === "TRLR");
    41→    const individuals = this.records.filter((r) => r.type === "INDI");
    42→    const families = this.records.filter((r) => r.type === "FAM");
    43→
    44→    if (!header) {
    45→      throw new Error("Missing required HEAD record");
    46→    }
    47→    if (!trailer) {
    48→      throw new Error("Missing required TRLR record");
    49→    }
    50→
    51→    // Extract charset and version from header
    52→    const charsetLine = header.tags.get("CHAR")?.[0];
    53→    const versionLine = header.tags.get("VERS")?.[0];
    54→    const gedcomLine = header.tags.get("GEDC")?.[0];
    55→    const gedcVersionLine = header.tags.get("GEDC")?.find((l) =>
    56→      l.tag === "VERS"
    57→    );
    58→
    59→    const charset = charsetLine?.value || "UTF-8";
    60→    const version = gedcVersionLine?.value || "5.5.1";
    61→
    62→    return {
    63→      header,
    64→      individuals,
    65→      families,
    66→      trailer,
    67→      version,
    68→      charset,
    69→    };
    70→  }
    71→
    72→  /**
    73→   * Parse lines and handle continuation lines (CONT/CONC)
    74→   */
    75→  private parseLines(rawLines: string[]): void {
    76→    let i = 0;
    77→    while (i < rawLines.length) {
    78→      const line = rawLines[i];
    79→      const parsedLine = this.parseLine(line);
    80→
    81→      if (!parsedLine) {
    82→        i++;
    83→        continue;
    84→      }
    85→
    86→      // Handle continuation lines
    87→      let continuedValue = parsedLine.value;
    88→      let nextIndex = i + 1;
    89→
    90→      while (nextIndex < rawLines.length) {
    91→        const nextLine = rawLines[nextIndex];
    92→        const nextParsed = this.parseLine(nextLine);
    93→
    94→        // Check if it's a continuation line (CONT or CONC)
    95→        if (!nextParsed) {
    96→          break;
    97→        }
    98→
    99→        // Check if next line is at higher level or lower level with continuation tags
   100→        const nextLevel = this.getLevel(nextLine);
   101→        const currentLevel = parsedLine.level;
   102→
   103→        if (nextLevel > currentLevel && (nextParsed.tag === "CONT" || nextParsed.tag === "CONC")) {
   104→          // CONT adds line break, CONC concatenates
   105→          if (nextParsed.tag === "CONT") {
   106→            continuedValue += "\n" + nextParsed.value;
   107→          } else {
   108→            continuedValue += nextParsed.value;
   109→          }
   110→          nextIndex++;
   111→        } else {
   112→          break;
   113→        }
   114→      }
   115→
   116→      parsedLine.value = continuedValue;
   117→      this.lines.push(parsedLine);
   118→      i = nextIndex;
   119→    }
   120→  }
   121→
   122→  /**
   123→   * Parse a single GEDCOM line
   124→   * Format: <level> <tag> [<xref>] [<value>]
   125→   */
   126→  private parseLine(line: string): GedcomLine | null {
   127→    // Match GEDCOM line pattern
   128→    // Level is required, tag is required, xref/value are optional
   129→    const match = line.match(/^(\d+)\s+(@[\w#]+@)?\s*(\w+)(?:\s+(@[\w#]+@|.*))?$/);
   130→
   131→    if (!match) {
   132→      return null;
   133→    }
   134→
   135→    const [, levelStr, xref, tag, valueOrPointer] = match;
   136→    const level = parseInt(levelStr, 10);
   137→
   138→    // Determine if valueOrPointer is a pointer or value
   139→    let pointer: string | undefined;
   140→    let value: string;
   141→
   142→    if (valueOrPointer?.match(/^@[\w#]+@$/)) {
   143→      pointer = valueOrPointer;
   144→      value = "";
   145→    } else {
   146→      value = valueOrPointer || "";
   147→    }
   148→
   149→    return {
   150→      level,
   151→      tag,
   152→      xref,
   153→      value: value.trim(),
   154→      pointer,
   155→    };
   156→  }
   157→
   158→  /**
   159→   * Get level from a line string
   160→   */
   161→  private getLevel(line: string): number {
   162→    const match = line.match(/^(\d+)\s+/);
   163→    return match ? parseInt(match[1], 10) : 0;
   164→  }
   165→
   166→  /**
   167→   * Build hierarchical record structure from lines
   168→   */
   169→  private buildRecords(): void {
   170→    const recordStack: GedcomRecord[] = [];
   171→    let currentRecord: GedcomRecord | null = null;
   172→    let currentParent: GedcomRecord | null = null;
   173→
   174→    for (const line of this.lines) {
   175→      // Top-level record
   176→      if (line.level === 0) {
   177→        // Save previous record
   178→        if (currentRecord) {
   179→          this.records.push(currentRecord);
   180→        }
   181→
   182→        const type = this.getRecordType(line.tag, line.xref);
   183→        currentRecord = {
   184→          type,
   185→          id: line.xref?.replace(/@/g, ""),
   186→          lines: [line],
   187→          tags: new Map(),
   188→        };
   189→        recordStack.length = 0;
   190→        recordStack.push(currentRecord);
   191→
   192→        // Add to tag map
   193→        const existing = currentRecord.tags.get(line.tag) || [];
   194→        existing.push(line);
   195→        currentRecord.tags.set(line.tag, existing);
   196→      } else if (currentRecord) {
   197→        // Add to current record
   198→        currentRecord.lines.push(line);
   199→
   200→        // Add to tag map
   201→        const existing = currentRecord.tags.get(line.tag) || [];
   202→        existing.push(line);
   203→        currentRecord.tags.set(line.tag, existing);
   204→      }
   205→    }
   206→
   207→    // Save last record
   208→    if (currentRecord) {
   209→      this.records.push(currentRecord);
   210→    }
   211→  }
   212→
   213→  /**
   214→   * Determine record type from tag
   215→   */
   216→  private getRecordType(
   217→    tag: string,
   218→    xref?: string
   219→  ): "INDI" | "FAM" | "HEAD" | "TRLR" | "OTHER" {
   220→    if (tag === "HEAD") return "HEAD";
   221→    if (tag === "TRLR") return "TRLR";
   222→    if (tag === "INDI") return "INDI";
   223→    if (tag === "FAM") return "FAM";
   224→    return "OTHER";
   225→  }
   226→
   227→  /**
   228→   * Parse GEDCOM date format
   229→   * Handles: "15 JAN 1985", "JAN 1985", "1985", "ABT 1985", "BEF 1985", "AFT 1985", "BET 1975 AND 1985"
   230→   * Returns ISO date (YYYY-MM-DD) or null if invalid/partial
   231→   */
   232→  parseDate(gedcomDate: string): string | null {
   233→    if (!gedcomDate || !gedcomDate.trim()) {
   234→      return null;
   235→    }
   236→
   237→    const trimmed = gedcomDate.trim();
   238→    const parsed = this.parseDateComponents(trimmed);
   239→
   240→    if (!parsed.year) {
   241→      return null;
   242→    }
   243→
   244→    // Validate day is reasonable
   245→    if (parsed.day && (parsed.day < 1 || parsed.day > 31)) {
   246→      return null;
   247→    }
   248→
   249→    // Build ISO date with available components
   250→    let isoDate = String(parsed.year).padStart(4, "0");
   251→
   252→    if (parsed.month) {
   253→      isoDate += "-" + String(parsed.month).padStart(2, "0");
   254→
   255→      if (parsed.day) {
   256→        isoDate += "-" + String(parsed.day).padStart(2, "0");
   257→      }
   258→    }
   259→
   260→    return isoDate;
   261→  }
   262→
   263→  /**
   264→   * Parse date components from GEDCOM date string
   265→   */
   266→  private parseDateComponents(dateStr: string): ParsedDate {
   267→    const result: ParsedDate = {
   268→      isApproximate: false,
   269→      raw: dateStr,
   270→    };
   271→
   272→    // Check for date qualifiers
   273→    let workingStr = dateStr.trim();
   274→    const qualifierMatch = workingStr.match(/^(ABT|BEF|AFT|BET)\s+/);
   275→    if (qualifierMatch) {
   276→      result.qualifier = qualifierMatch[1] as any;
   277→      result.isApproximate = true;
   278→      workingStr = workingStr.substring(qualifierMatch[0].length).trim();
   279→    }
   280→
   281→    // Handle "BET ... AND ..." format (e.g., "BET 1975 AND 1985" or "BET 1 JAN 1975 AND 1 JAN 1985")
   282→    if (result.qualifier === "BET") {
   283→      // Try full date format first: "BET 15 JAN 1975 AND 15 JAN 1985"
   284→      const betFullMatch = workingStr.match(
   285→        /^(\d{1,2})\s+(\w+)\s+(\d{4})\s+AND\s+(\d{1,2})\s+(\w+)\s+(\d{4})$/
   286→      );
   287→      if (betFullMatch) {
   288→        result.day = parseInt(betFullMatch[1], 10);
   289→        result.month = this.monthToNumber(betFullMatch[2]);
   290→        result.year = parseInt(betFullMatch[3], 10);
   291→        return result;
   292→      }
   293→
   294→      // Try year-only format: "BET 1975 AND 1985"
   295→      const betYearMatch = workingStr.match(/^(\d{4})\s+AND\s+(\d{4})$/);
   296→      if (betYearMatch) {
   297→        result.year = parseInt(betYearMatch[1], 10);
   298→        return result;
   299→      }
   300→    }
   301→
   302→    // Try full date format: "15 JAN 1985"
   303→    const fullMatch = workingStr.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})$/);
   304→    if (fullMatch) {
   305→      result.day = parseInt(fullMatch[1], 10);
   306→      result.month = this.monthToNumber(fullMatch[2]);
   307→      result.year = parseInt(fullMatch[3], 10);
   308→      return result;
   309→    }
   310→
   311→    // Try month-year format: "JAN 1985"
   312→    const monthYearMatch = workingStr.match(/^(\w+)\s+(\d{4})$/);
   313→    if (monthYearMatch) {
   314→      result.month = this.monthToNumber(monthYearMatch[1]);
   315→      result.year = parseInt(monthYearMatch[2], 10);
   316→      return result;
   317→    }
   318→
   319→    // Try year only: "1985"
   320→    const yearMatch = workingStr.match(/^(\d{4})$/);
   321→    if (yearMatch) {
   322→      result.year = parseInt(yearMatch[1], 10);
   323→      return result;
   324→    }
   325→
   326→    return result;
   327→  }
   328→
   329→  /**
   330→   * Convert month name to number (1-12)
   331→   */
   332→  private monthToNumber(monthName: string): number | undefined {
   333→    const months: Record<string, number> = {
   334→      JAN: 1,
   335→      FEB: 2,
   336→      MAR: 3,
   337→      APR: 4,
   338→      MAY: 5,
   339→      JUN: 6,
   340→      JUL: 7,
   341→      AUG: 8,
   342→      SEP: 9,
   343→      SEPT: 9,
   344→      OCT: 10,
   345→      NOV: 11,
   346→      DEC: 12,
   347→    };
   348→    return months[monthName.toUpperCase()];
   349→  }
   350→
   351→  /**
   352→   * Parse name in GEDCOM format
   353→   * Format: "Given /Surname/" or "Given" or "/Surname/"
   354→   */
   355→  parseName(gedcomName: string): { firstName?: string; lastName?: string } {
   356→    if (!gedcomName || !gedcomName.trim()) {
   357→      return {};
   358→    }
   359→
   360→    const trimmed = gedcomName.trim();
   361→
   362→    // Find surname between forward slashes
   363→    const surnameMatch = trimmed.match(/\/([^\/]*)\//);
   364→    const lastName = surnameMatch ? surnameMatch[1].trim() : undefined;
   365→
   366→    // Extract given names (everything before and after surname)
   367→    let firstName: string | undefined;
   368→    if (surnameMatch) {
   369→      // Remove the /surname/ part and trim
   370→      const withoutSurname = trimmed
   371→        .replace(/\/[^\/]*\//, "")
   372→        .trim();
   373→      firstName = withoutSurname || undefined;
   374→    } else {
   375→      // No surname markers, entire thing is given name
   376→      firstName = trimmed || undefined;
   377→    }
   378→
   379→    return {
   380→      firstName: firstName || undefined,
   381→      lastName: lastName || undefined,
   382→    };
   383→  }
   384→
   385→  /**
   386→   * Validate GEDCOM file structure
   387→   */
   388→  validate(file: GedcomFile): ValidationError[] {
   389→    const errors: ValidationError[] = [];
   390→
   391→    // Check for required records
   392→    if (!file.header) {
   393→      errors.push({
   394→        message: "Missing required HEAD record",
   395→        severity: "error",
   396→      });
   397→    }
   398→
   399→    if (!file.trailer) {
   400→      errors.push({
   401→        message: "Missing required TRLR record",
   402→        severity: "error",
   403→      });
   404→    }
   405→
   406→    // Check for unique xrefs
   407→    const xrefSet = new Set<string>();
   408→    const allRecords = [
   409→      file.header,
   410→      ...file.individuals,
   411→      ...file.families,
   412→      file.trailer,
   413→    ].filter((r): r is GedcomRecord => r !== null && r !== undefined);
   414→
   415→    for (const record of allRecords) {
   416→      if (record.id) {
   417→        if (xrefSet.has(record.id)) {
   418→          errors.push({
   419→            message: `Duplicate xref: ${record.id}`,
   420→            severity: "error",
   421→          });
   422→        }
   423→        xrefSet.add(record.id);
   424→      }
   425→    }
   426→
   427→    // Check for broken references in families
   428→    const personIds = new Set(file.individuals.map((i) => i.id));
   429→    const familyIds = new Set(file.families.map((f) => f.id));
   430→
   431→    for (const family of file.families) {
   432→      const husbandLine = family.tags.get("HUSB")?.[0];
   433→      const wifeLine = family.tags.get("WIFE")?.[0];
   434→      const childLines = family.tags.get("CHIL") || [];
   435→
   436→      if (husbandLine?.pointer && !personIds.has(husbandLine.pointer.replace(/@/g, ""))) {
   437→        errors.push({
   438→          message: `Broken reference in family ${family.id}: HUSB ${husbandLine.pointer} not found`,
   439→          severity: "warning",
   440→        });
   441→      }
   442→
   443→      if (wifeLine?.pointer && !personIds.has(wifeLine.pointer.replace(/@/g, ""))) {
   444→        errors.push({
   445→          message: `Broken reference in family ${family.id}: WIFE ${wifeLine.pointer} not found`,
   446→          severity: "warning",
   447→        });
   448→      }
   449→
   450→      for (const childLine of childLines) {
   451→        if (childLine.pointer && !personIds.has(childLine.pointer.replace(/@/g, ""))) {
   452→          errors.push({
   453→            message: `Broken reference in family ${family.id}: CHIL ${childLine.pointer} not found`,
   454→            severity: "warning",
   455→          });
   456→        }
   457→      }
   458→    }
   459→
   460→    // Check for broken family references in individuals
   461→    for (const person of file.individuals) {
   462→      const famcLines = person.tags.get("FAMC") || [];
   463→      const famsLines = person.tags.get("FAMS") || [];
   464→
   465→      for (const line of famcLines) {
   466→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   467→          errors.push({
   468→            message: `Broken reference in person ${person.id}: FAMC ${line.pointer} not found`,
   469→            severity: "warning",
   470→          });
   471→        }
   472→      }
   473→
   474→      for (const line of famsLines) {
   475→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   476→          errors.push({
   477→            message: `Broken reference in person ${person.id}: FAMS ${line.pointer} not found`,
   478→            severity: "warning",
   479→          });
   480→        }
   481→      }
   482→    }
   483→
   484→    return errors;
   485→  }
   486→
   487→  /**
   488→   * Parse individual record into structured data
   489→   */
   490→  parseIndividual(record: GedcomRecord): ParsedIndividual {
   491→    const id = record.id || "unknown";
   492→
   493→    // Extract names
   494→    const names: Array<{
   495→      full: string;
   496→      firstName?: string;
   497→      lastName?: string;
   498→    }> = [];
   499→    const nameLines = record.tags.get("NAME") || [];
   500→    for (const line of nameLines) {
   501→      const { firstName, lastName } = this.parseName(line.value);
   502→      names.push({
   503→        full: line.value,
   504→        firstName,
   505→        lastName,
   506→      });
   507→    }
   508→
   509→    // Extract sex
   510→    const sexLine = record.tags.get("SEX")?.[0];
   511→    const sex =
   512→      sexLine?.value === "M" || sexLine?.value === "F" || sexLine?.value === "X"
   513→        ? sexLine.value
   514→        : undefined;
   515→
   516→    // Extract birth information
   517→    const birtLine = record.tags.get("BIRT")?.[0];
   518→    const birthDate = birtLine
   519→      ? this.parseDateFromRecord(record, "BIRT")
   520→      : undefined;
   521→    const birthPlace = this.getPlaceFromEvent(record, "BIRT");
   522→
   523→    // Extract death information
   524→    const deathLine = record.tags.get("DEAT")?.[0];
   525→    const deathDate = deathLine
   526→      ? this.parseDateFromRecord(record, "DEAT")
   527→      : undefined;
   528→    const deathPlace = this.getPlaceFromEvent(record, "DEAT");
   529→
   530→    // Extract occupation
   531→    const occuLine = record.tags.get("OCCU")?.[0];
   532→    const occupation = occuLine?.value;
   533→
   534→    // Extract notes (skip empty notes)
   535→    const notes: string[] = [];
   536→    const noteLines = record.tags.get("NOTE") || [];
   537→    for (const line of noteLines) {
   538→      const noteValue = line.value.trim();
   539→      if (noteValue) {
   540→        notes.push(noteValue);
   541→      }
   542→    }
   543→
   544→    // Extract family references
   545→    const familiesAsChild: string[] = [];
   546→    const famcLines = record.tags.get("FAMC") || [];
   547→    for (const line of famcLines) {
   548→      if (line.pointer) {
   549→        familiesAsChild.push(line.pointer.replace(/@/g, ""));
   550→      }
   551→    }
   552→
   553→    const familiesAsSpouse: string[] = [];
   554→    const famsLines = record.tags.get("FAMS") || [];
   555→    for (const line of famsLines) {
   556→      if (line.pointer) {
   557→        familiesAsSpouse.push(line.pointer.replace(/@/g, ""));
   558→      }
   559→    }
   560→
   561→    return {
   562→      id,
   563→      names: names.length > 0 ? names : [{ full: "" }],
   564→      sex,
   565→      birthDate,
   566→      birthPlace,
   567→      deathDate,
   568→      deathPlace,
   569→      occupation,
   570→      notes,
   571→      familiesAsChild,
   572→      familiesAsSpouse,
   573→    };
   574→  }
   575→
   576→  /**
   577→   * Parse family record into structured data
   578→   */
   579→  parseFamily(record: GedcomRecord): ParsedFamily {
   580→    const id = record.id || "unknown";
   581→
   582→    // Extract spouse information
   583→    const husbandLine = record.tags.get("HUSB")?.[0];
   584→    const wifeLine = record.tags.get("WIFE")?.[0];
   585→    const husband = husbandLine?.pointer?.replace(/@/g, "");
   586→    const wife = wifeLine?.pointer?.replace(/@/g, "");
   587→
   588→    // Extract children
   589→    const children: string[] = [];
   590→    const childLines = record.tags.get("CHIL") || [];
   591→    for (const line of childLines) {
   592→      if (line.pointer) {
   593→        children.push(line.pointer.replace(/@/g, ""));
   594→      }
   595→    }
   596→
   597→    // Extract marriage information
   598→    const marriageDate = this.parseDateFromRecord(record, "MARR");
   599→    const marriagePlace = this.getPlaceFromEvent(record, "MARR") || undefined;
   600→
   601→    // Extract divorce information
   602→    const divorceDate = this.parseDateFromRecord(record, "DIV");
   603→
   604→    // Extract notes (skip empty notes)
   605→    const notes: string[] = [];
   606→    const noteLines = record.tags.get("NOTE") || [];
   607→    for (const line of noteLines) {
   608→      const noteValue = line.value.trim();
   609→      if (noteValue) {
   610→        notes.push(noteValue);
   611→      }
   612→    }
   613→
   614→    return {
   615→      id,
   616→      husband,
   617→      wife,
   618→      children,
   619→      marriageDate,
   620→      marriagePlace,
   621→      divorceDate,
   622→      notes,
   623→    };
   624→  }
   625→
   626→  /**
   627→   * Parse date from an event tag (BIRT, DEAT, MARR, etc.)
   628→   */
   629→  private parseDateFromRecord(
   630→    record: GedcomRecord,
   631→    eventTag: string
   632→  ): string | undefined {
   633→    const eventLines = record.tags.get(eventTag) || [];
   634→    for (const eventLine of eventLines) {
   635→      // Look for DATE substructure
   636→      const eventIndex = record.lines.indexOf(eventLine);
   637→
   638→      // Find DATE lines that are children of this event
   639→      for (let i = eventIndex + 1; i < record.lines.length; i++) {
   640→        const line = record.lines[i];
   641→
   642→        // Stop if we reach a line at the same or lower level as the event
   643→        if (line.level <= eventLine.level) {
   644→          break;
   645→        }
   646→
   647→        // Found a DATE child of this event
   648→        if (line.tag === "DATE") {
   649→          const parsed = this.parseDate(line.value);
   650→          if (parsed) {
   651→            return parsed;
   652→          }
   653→        }
   654→      }
   655→    }
   656→    return undefined;
   657→  }
   658→
   659→  /**
   660→   * Get place from event tag
   661→   */
   662→  private getPlaceFromEvent(
   663→    record: GedcomRecord,
   664→    eventTag: string
   665→  ): string | undefined {
   666→    const eventLines = record.tags.get(eventTag) || [];
   667→    for (const eventLine of eventLines) {
   668→      // Look for PLAC substructure
   669→      const eventIndex = record.lines.indexOf(eventLine);
   670→      for (let i = eventIndex + 1; i < record.lines.length; i++) {
   671→        const line = record.lines[i];
   672→        if (line.level <= eventLine.level) {
   673→          break;
   674→        }
   675→        if (line.tag === "PLAC") {
   676→          return line.value;
   677→        }
   678→      }
   679→    }
   680→    return undefined;
   681→  }
   682→}
